watchPlatformMode(()=>{});
const state={role:sessionStorage.getItem('nautilus-role')||null,staffName:sessionStorage.getItem('nautilus-staff-name')||null,lastSubmission:null,installPrompt:null,qrStream:null,modalReturnFocus:null,sightingStep:1};
