const esc=(s='')=>String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmt=d=>d?new Intl.DateTimeFormat(locale(),{dateStyle:'medium',timeStyle:'short'}).format(new Date(d)):'—';
const fmtDate=d=>d?new Intl.DateTimeFormat(locale(),{dateStyle:'medium'}).format(new Date(d)):'—';
const route=()=>((location.hash.slice(1)||'/').split('?')[0]);
const go=p=>location.hash=p;
const query=()=>new URLSearchParams((location.hash.split('?')[1]||''));
const human=v=>String(v??'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const daysAgo=d=>{ if(!d)return'—'; const n=Math.max(0,Math.floor((Date.now()-new Date(d))/86400000)); return n===0?tr('today'):`${n} ${tr('daysAgo')}`; };
const safeImageUrl=u=>{if(!u||typeof u!=='string')return './assets/tortoise-placeholder.svg';try{const x=new URL(u,location.href);return ['https:','http:'].includes(x.protocol)&&(!u.startsWith('http')||x.origin===location.origin||x.hostname.endsWith('.supabase.co'))?x.href:'./assets/tortoise-placeholder.svg';}catch{return './assets/tortoise-placeholder.svg';}};

function mobileMenuLinks(){
  if(route().startsWith('/staff/') && state.role){
    const links=[['dashboard',tr('dashboard')],['insights',tr('insights')],['animals',tr('animals')],['observations',tr('observations')],['health',tr('health')]];
    if(['ranger','researcher','admin'].includes(state.role))links.push(['spatial',tr('mapLab')]);
    if(['researcher','admin'].includes(state.role))links.push(['research',tr('research')],['devices',tr('devices')],['export',tr('exportData')]);
    if(state.role==='admin')links.push(['qr',tr('qrCodes')],['audit',tr('audit')],['settings',tr('settings')]);
    return links.map(([id,label])=>`<a data-nav="/staff/${id}" href="#/staff/${id}">${label}</a>`).join('')+`<a href="#/logout">${tr('logout')}</a>`;
  }
  return `<a data-nav="/directory" href="#/directory">${tr('directory')}</a><a data-nav="/about" href="#/about">${tr('about')}</a><a data-nav="/privacy" href="#/privacy">${tr('privacy')}</a><a data-nav="/login" href="#/login">${tr('staff')}</a>`;
}
function appTabbar(){
  if(route().startsWith('/staff/') && state.role){
    const third=['ranger','researcher','admin'].includes(state.role)?['/staff/spatial','⌖',tr('mapLab')]:['/staff/insights','▥',tr('insights')];
    return `<nav class="app-tabbar" aria-label="${tr('appNavigation')}"><a data-nav="/staff/dashboard" href="#/staff/dashboard"><span aria-hidden="true">⌂</span><b>${tr('dashboard')}</b></a><a data-nav="/staff/animals" href="#/staff/animals"><span aria-hidden="true">🐢</span><b>${tr('animals')}</b></a><a data-nav="${third[0]}" href="#${third[0]}"><span aria-hidden="true">${third[1]}</span><b>${third[2]}</b></a><a data-nav="/staff/health" href="#/staff/health"><span aria-hidden="true">＋</span><b>${tr('health')}</b></a><button type="button" id="app-more-button" aria-expanded="false" aria-controls="mobile-menu"><span aria-hidden="true">•••</span><b>${tr('more')}</b></button></nav>`;
  }
  return `<nav class="app-tabbar" aria-label="${tr('appNavigation')}"><a data-nav="/" href="#/"><span aria-hidden="true">⌂</span><b>${tr('home')}</b></a><a data-nav="/identify" href="#/identify"><span aria-hidden="true">▣</span><b>${tr('identify')}</b></a><a data-nav="/map" href="#/map"><span aria-hidden="true">⌖</span><b>${tr('explore')}</b></a><a data-nav="/insights" href="#/insights"><span aria-hidden="true">▥</span><b>${tr('insights')}</b></a><button type="button" id="app-more-button" aria-expanded="false" aria-controls="mobile-menu"><span aria-hidden="true">•••</span><b>${tr('more')}</b></button></nav>`;
}
function shell(content){
  const pendingId='pending-count-global';
  return `<a class="skip-link" href="#main-content">${getLanguage()==='af'?'Spring na hoofinhoud':'Skip to main content'}</a>
  <header class="site-header"><a class="brand" href="#/" aria-label="${esc(cfg.appName)}"><span class="brand-emblem" aria-hidden="true">🐢</span><span class="brand-copy"><strong>Nautilus Bay</strong><small>${tr('appName')}</small></span></a>
  <nav class="desktop-nav" aria-label="${tr('primaryNavigation')}"><a data-nav="/" href="#/">${tr('home')}</a><a data-nav="/identify" href="#/identify">${tr('identify')}</a><a data-nav="/directory" href="#/directory">${tr('directory')}</a><a data-nav="/map" href="#/map">${tr('explore')}</a><a data-nav="/insights" href="#/insights">${tr('insights')}</a><a data-nav="/about" href="#/about">${tr('about')}</a><a data-nav="/login" href="#/login">${tr('staff')}</a></nav>
  <div class="header-actions"><span class="app-mode-badge" aria-hidden="true">${platform.native?'APP':platform.standalone?'PWA':''}</span><button class="quiet-btn" id="language-btn" aria-label="${tr('changeLanguage')}">${getLanguage()==='en'?'AF':'EN'}</button></div></header>
  <button id="mobile-menu-scrim" class="mobile-menu-scrim" hidden aria-label="${tr('closeMenu')}"></button><nav id="mobile-menu" class="mobile-menu app-sheet" hidden aria-label="${tr('mobileNavigation')}"><div class="sheet-handle" aria-hidden="true"></div><div class="sheet-head"><strong>${tr('more')}</strong><button class="quiet-btn" id="mobile-menu-close" aria-label="${tr('closeMenu')}">×</button></div>${mobileMenuLinks()}<button class="text-button app-install-action" data-install-button hidden>${tr('install')}</button></nav>
  <div id="network-slot"></div><div id="update-slot" class="update-slot" hidden></div>
  <main id="main-content" tabindex="-1">${content}</main>
  <footer class="site-footer"><div><strong>${tr('reserve')}</strong><span>${tr('footerTagline')}</span></div><div class="footer-links"><a href="#/privacy">${tr('privacy')}</a><a href="#/about">${tr('about')}</a><button class="text-button" data-install-button hidden>${tr('install')}</button></div></footer>
  ${appTabbar()}<div class="sync-pill" id="${pendingId}" hidden></div><div class="toast" id="toast" role="status" aria-live="polite"></div><div id="dialog-root"></div>`;
}

function toast(message,type=''){ const e=document.querySelector('#toast'); if(!e)return; e.textContent=message; e.className=`toast show ${type}`; clearTimeout(toast.timer); toast.timer=setTimeout(()=>e.className='toast',3200); }
function modal(html){
  const root=document.querySelector('#dialog-root'); state.modalReturnFocus=document.activeElement;
  root.innerHTML=`<dialog class="modal" aria-modal="true"><div class="modal-inner">${html}</div></dialog>`;
  const d=root.querySelector('dialog');
  const close=()=>{ try{d.close();}catch{} root.innerHTML=''; state.modalReturnFocus?.focus?.(); };
  d.addEventListener('cancel',e=>{e.preventDefault();close();});
  d.addEventListener('click',e=>{if(e.target===d)close();});
  root.querySelectorAll('[data-close]').forEach(b=>b.onclick=close);
  d.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const focusable=[...d.querySelectorAll('button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])')].filter(x=>!x.disabled&&!x.hidden);if(!focusable.length)return;const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
  d.showModal(); requestAnimationFrame(()=>d.querySelector('input,select,textarea,button')?.focus()); return root;
}
function pageHead(eyebrow,title,text=''){ return `<div class="page-heading"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${text?`<p class="lede">${text}</p>`:''}</div>`; }
function stat(value,label,extra=''){ return `<div class="stat-card"><strong>${esc(value)}</strong><span>${label}</span>${extra?`<small>${extra}</small>`:''}</div>`; }
function animalCard(a){ const common=getLanguage()==='af'?(a.common_name_af||a.common_name_en):(a.common_name_en||a.common_name_af); return `<article class="animal-card"><a href="#/t/${a.public_id}" aria-label="${tr('meet')} ${esc(a.name||a.public_id)}"><div class="animal-visual"><img src="${esc(safeImageUrl(a.profile_photo_url))}" alt="${esc(a.name?tr('profilePhotoOf')+' '+a.name:tr('tortoiseProfilePhoto'))}" loading="lazy"><div class="animal-id">${esc(a.public_id)}</div></div><div class="animal-card-copy"><div class="kicker">${esc(common||tr('tortoiseGeneric'))}</div><h3>${esc(a.name||a.public_id)}</h3><p><em>${esc(a.scientific_name||'')}</em></p><span class="arrow-link">${tr('meet')} ${esc(a.name||a.public_id)} →</span></div></a></article>`; }

async function homeView(){
  const animals=await Repo.publicAnimals(); const map=await Repo.publicMap();
  const month=new Date().getMonth(),year=new Date().getFullYear(); const thisMonth=map.filter(o=>{const d=new Date(o.observed_at);return d.getMonth()===month&&d.getFullYear()===year;}).length;
  let verified='—',health='—'; if(isDemo()){ const all=DemoDB.observations(); verified=all.length?`${Math.round(100*all.filter(o=>o.verification_status==='verified').length/all.length)}%`:'—'; health=DemoDB.all('health_cases').filter(c=>c.status!=='closed').length; }
  return `<section class="hero"><div class="hero-pattern" aria-hidden="true"></div><div class="hero-content"><div class="eyebrow light">${tr('heroEyebrow')}</div><h1>${tr('heroTitle')}</h1><p>${tr('heroText')}</p><div class="hero-actions"><a class="btn primary light" href="#/scan">▣ ${tr('scanQr')}</a><a class="btn secondary light" href="#/identify">${tr('enterId')}</a></div><div class="safety-note"><span aria-hidden="true">◌</span><span>${tr('observeSafely')}</span></div></div><div class="hero-orbit" aria-hidden="true"><div class="orbit-shell">🐢</div></div></section>
  <section class="section overlap"><div class="stats-grid">${stat(animals.length,tr('registeredAnimals'))}${stat(thisMonth,tr('sightingsMonth'))}${stat(verified,tr('verifiedRate'))}${stat(health,tr('healthAlerts'))}</div></section>
  <section class="section split-intro"><div>${pageHead(tr('communityScience'),tr('recentTortoises'),'')}</div><div class="intro-actions"><a class="btn secondary" href="#/untagged">${tr('reportUntagged')}</a><a class="text-link" href="#/directory">${tr('exploreTortoises')} →</a></div></section>
  <section class="section cards-grid">${animals.slice(0,6).map(animalCard).join('')||`<div class="empty">${tr('noRecords')}</div>`}</section>
  <section class="section impact-panel"><div><div class="eyebrow">${tr('conservationByDesign')}</div><h2>${tr('aboutTitle')}</h2><p>${tr('aboutText')}</p></div><div class="impact-list"><div><strong>01</strong><span>${tr('aboutScience')}</span></div><div><strong>02</strong><span>${tr('aboutOffline')}</span></div><div><strong>03</strong><span>${tr('aboutFuture')}</span></div></div></section>`;
}

